def h(value):
    """Escape user-editable text for safe HTML rendering."""
    return html.escape(str(value) if value is not None else '', quote=True)


def load_data():
    if not DATA_PATH.exists():
        DATA_PATH.write_text(json.dumps(DEFAULT_DATA, ensure_ascii=False, indent=2) + '\n', encoding='utf-8')
        return copy.deepcopy(DEFAULT_DATA)
    data = json.loads(DATA_PATH.read_text(encoding='utf-8'))
    if not isinstance(data, dict):
        raise ValueError('site_data.json should contain a JSON object')
    merged = copy.deepcopy(DEFAULT_DATA)
    for key, value in data.items():
        if key == 'recruitment' and isinstance(value, dict):
            merged['recruitment'].update(value)
        elif key in merged:
            merged[key] = value
    for key in ('news', 'matches', 'players'):
        if not isinstance(merged.get(key), list):
            merged[key] = []
    return merged


def render_news(data):
    news = data.get('news', [])
    if not news:
        return '<div class="empty"><div class="empty-icon">N</div><strong>등록된 구단 소식이 없습니다.</strong><p>새로운 공지사항은 이곳에 게시됩니다.</p></div>'
    items = []
    for item in news[:6]:
        if not isinstance(item, dict):
            continue
        items.append('<article class="news-item"><span class="date-label">{}</span><h3>{}</h3><p>{}</p></article>'.format(
            h(item.get('date','날짜 미정')), h(item.get('title','소식')), h(item.get('summary',''))))
    return ''.join(items) if items else '<div class="empty">등록된 소식이 없습니다.</div>'


def render_next_match(data):
    matches = [i for i in data.get('matches', []) if isinstance(i, dict)]
    if not matches:
        return '<div class="empty"><div class="empty-icon">—</div><strong>예정된 경기가 없습니다.</strong><p>일정 확정 후 업데이트됩니다.</p></div>'
    m = matches[0]
    return '<div class="empty"><span class="date-label">{}</span><strong style="margin-top:12px">{} vs {}</strong><p>{}</p></div>'.format(
        h(m.get('date','날짜 미정')), h(m.get('home','운천 FC')), h(m.get('away','상대 미정')), h(m.get('place','장소 미정')))


def render_players(data):
    players = [p for p in data.get('players', []) if isinstance(p, dict)]
    if not players:
        return '<div class="small-alert" style="margin:14px 14px 0">현재 공개된 선수 명단이 없습니다. 공식 명단 등록 후 갱신됩니다.</div>'
    cards = []
    for p in players:
        cards.append('<div class="player"><div class="player-inner"><div class="player-num">{}</div><strong class="player-name">{}</strong><span class="player-pos">{}</span></div></div>'.format(
            h(p.get('number','-')), h(p.get('name','미등록')), h(p.get('position','-'))))
    return ''.join(cards)


def render_matches(data):
    matches = [m for m in data.get('matches', []) if isinstance(m, dict)]
    if not matches:
        return '<div class="match-empty"><div class="empty"><div class="empty-icon">&#9917;</div><strong>등록된 경기 일정이 없습니다.</strong><p>경기 일정이 확정되면 이곳에 공개합니다.</p></div></div>'
    rows = []
    for m in matches:
        rows.append('<tr><td>{}</td><td><strong>{} vs {}</strong></td><td>{}</td><td>{}</td></tr>'.format(
            h(m.get('date','날짜 미정')), h(m.get('home','운천 FC')), h(m.get('away','상대 미정')), h(m.get('place','장소 미정')), h(m.get('note','예정'))))
    return '<table class="match-table"><thead><tr><th>날짜 / 시간</th><th>대진</th><th>장소</th><th>구분</th></tr></thead><tbody>{}</tbody></table>'.format(''.join(rows))


def render_contact(data):
    email = str(data.get('contact_email','')).strip()
    instagram = str(data.get('instagram_url','')).strip()
    parts = []
    if email and re.match(r'^[^\s@]+@[^\s@]+\.[^\s@]+$', email):
        parts.append('<a href="mailto:{}">{}</a>'.format(h(email),h(email)))
    if instagram.startswith('https://') or instagram.startswith('http://'):
        parts.append('<a href="{}" target="_blank" rel="noopener">Instagram</a>'.format(h(instagram)))
    return ' &nbsp;·&nbsp; '.join(parts) if parts else '<span style="color:#667c9b">공식 연락처 등록 예정</span>'




def public_base_url():
    """Return only a configured HTTPS public URL, never an untrusted Host header.

    Render provides RENDER_EXTERNAL_URL automatically. PUBLIC_SITE_URL may override
    it when a custom domain is connected.
    """
    from urllib.parse import urlsplit
    candidate = (os.environ.get('PUBLIC_SITE_URL') or
                 os.environ.get('RENDER_EXTERNAL_URL') or '').strip().rstrip('/')
    if not candidate:
        return ''
    parsed = urlsplit(candidate)
    if (parsed.scheme != 'https' or not parsed.netloc or parsed.username or
        parsed.password or parsed.query or parsed.fragment or parsed.path or
        not re.fullmatch(r'[A-Za-z0-9.-]+(?::[0-9]{1,5})?', parsed.netloc)):
        return ''
    return candidate


def seo_meta(data):
    """SEO tags and optional verified ownership tags; token values are never guessed."""
    base = public_base_url()
    description = '운천 FC(UNCHEON FC) 공식 홈페이지. 구단 소개, 선수단, 경기 일정, 공지사항 및 입단 안내.'
    tags = [
        '<meta name="robots" content="index, follow, max-image-preview:large">',
        '<meta property="og:type" content="website">',
        '<meta property="og:locale" content="ko_KR">',
        '<meta property="og:site_name" content="{}">'.format(h(data.get('club_name', '운천 FC'))),
        '<meta property="og:title" content="{} | 공식 홈페이지">'.format(h(data.get('club_name', '운천 FC'))),
        '<meta property="og:description" content="{}">'.format(h(description)),
        '<meta name="twitter:card" content="summary_large_image">',
    ]
    if base:
        canonical_url = base + '/'
        tags.extend([
            '<link rel="canonical" href="{}">'.format(h(canonical_url)),
            '<meta property="og:url" content="{}">'.format(h(canonical_url)),
            '<meta property="og:image" content="{}">'.format(h(base + '/media/artwork.jpg')),
        ])
    for variable, name in (('NAVER_SITE_VERIFICATION', 'naver-site-verification'),
                           ('GOOGLE_SITE_VERIFICATION', 'google-site-verification')):
        token = os.environ.get(variable, '').strip()
        if token:
            tags.append('<meta name="{}" content="{}">'.format(name, h(token)))
    return '\n'.join(tags)


def robots_text():
    result = 'User-agent: *\nAllow: /\n'
    base = public_base_url()
    if base:
        result += 'Sitemap: {}/sitemap.xml\n'.format(base)
    return result.encode('utf-8')


def sitemap_xml():
    base = public_base_url()
    if not base:
        return None
    return ('<?xml version="1.0" encoding="UTF-8"?>\n'
            '<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">\n'
            '  <url><loc>{}/</loc></url>\n'
            '</urlset>\n'.format(h(base))).encode('utf-8')

def render_home(data):
    recruitment = data.get('recruitment') or {}
    if not isinstance(recruitment, dict):
        recruitment = DEFAULT_DATA['recruitment']
    return HTML.substitute(
        css=CSS, year=datetime.now().year, seo_meta=seo_meta(data),
        club_name=h(data.get('club_name')), club_name_en=h(data.get('club_name_en')),
        season_label=h(data.get('season_label')), hero_title=h(data.get('hero_title')),
        hero_description=h(data.get('hero_description')), club_intro=h(data.get('club_intro')),
        activity_area=h(data.get('activity_area')), established=h(data.get('established')),
        notice=h(data.get('notice')), news_html=render_news(data), next_match_html=render_next_match(data),
        players_html=render_players(data), matches_html=render_matches(data), contact_html=render_contact(data),
        recruitment_status=h(recruitment.get('status','모집 안내')),
        recruitment_target=h(recruitment.get('target','문의')),
        recruitment_details=h(recruitment.get('details','')),
        form_note=h(recruitment.get('form_note','')),
    ).encode('utf-8')


class SiteHandler(BaseHTTPRequestHandler):
    server_version = 'UncheonFC/1.0'
    def do_GET(self):
        path = urlsplit(self.path).path
        if path in ('/', '/index.html'):
            try:
                body = render_home(load_data())
            except (OSError, ValueError, json.JSONDecodeError) as exc:
                self.respond(500, ('설정 파일을 확인해주세요: ' + str(exc)).encode('utf-8'), 'text/plain; charset=utf-8')
                return
            self.respond(200, body, 'text/html; charset=utf-8')
        elif path in ('/media/emblem.png', '/favicon.ico'):
            self.respond(200, EMBLEM, 'image/png', cache=True)
        elif path == '/media/artwork.jpg':
            self.respond(200, ARTWORK, 'image/jpeg', cache=True)
        elif path == '/join-form.pdf':
            self.respond(200, APPLICATION, 'application/pdf', extra={'Content-Disposition': 'attachment; filename="UncheonFC_Application.pdf"'})
        elif path == '/robots.txt':
            self.respond(200, robots_text(), 'text/plain; charset=utf-8')
        elif path == '/sitemap.xml':
            sitemap = sitemap_xml()
            if sitemap is None:
                self.respond(503, '배포 주소 설정 전입니다.'.encode('utf-8'), 'text/plain; charset=utf-8')
            else:
                self.respond(200, sitemap, 'application/xml; charset=utf-8')
        elif path == '/healthz':
            self.respond(200, b'ok', 'text/plain; charset=utf-8')
        else:
            self.respond(404, '요청하신 페이지를 찾을 수 없습니다.'.encode('utf-8'), 'text/plain; charset=utf-8')

    def do_HEAD(self):
        # HEAD provides compatibility with crawlers and older browser behavior.
        p = urlsplit(self.path).path
        if p in ('/', '/index.html', '/media/emblem.png', '/favicon.ico', '/media/artwork.jpg', '/join-form.pdf'):
            self.send_response(200)
            self.send_header('Content-Type', ('text/html; charset=utf-8' if p in ('/','/index.html') else 'image/png' if p in ('/media/emblem.png','/favicon.ico') else 'image/jpeg' if p == '/media/artwork.jpg' else 'application/xml; charset=utf-8' if p == '/sitemap.xml' else 'text/plain; charset=utf-8' if p in ('/robots.txt','/healthz') else 'application/pdf'))
            self.send_header('X-Content-Type-Options', 'nosniff')
            self.end_headers()
        else:
            self.send_error(404)

    def respond(self, code, body, content_type, cache=False, extra=None):
        self.send_response(code)
        self.send_header('Content-Type', content_type)
        self.send_header('Content-Length', str(len(body)))
        self.send_header('X-Content-Type-Options', 'nosniff')
        self.send_header('Referrer-Policy', 'no-referrer')
        self.send_header('Cache-Control', 'public, max-age=3600' if cache else 'no-cache')
        if extra:
            for name, value in extra.items():
                self.send_header(name, value)
        self.end_headers()
        self.wfile.write(body)


def main(argv=None):
    parser = argparse.ArgumentParser(description='운천 FC 공식 홈페이지 · Python 표준 라이브러리 전용')
    parser.add_argument('--host', default='127.0.0.1', help='기본값: 127.0.0.1 (내 컴퓨터에서만 접근)')
    parser.add_argument('--port', default=8000, type=int, help='기본값: 8000')
    args = parser.parse_args(argv)
    try:
        load_data()
        server = ThreadingHTTPServer((args.host, args.port), SiteHandler)
    except (OSError, ValueError) as exc:
        print('서버 시작 실패:', exc, file=sys.stderr)
        return 1
    print('\n운천 FC 공식 홈페이지를 실행했습니다.')
    print('접속 주소: http://{}:{}/'.format(args.host, args.port))
    print('공지/명단/일정 수정: {}'.format(DATA_PATH))
    print('종료: Ctrl+C\n')
    try:
        server.serve_forever()
    except KeyboardInterrupt:
        pass
    finally:
        server.server_close()
    return 0


if __name__ == '__main__':
    sys.exit(main())
